window.HOEREN_TESTS[35] = {"id":"studium-und-universitaet","name":"Studium und Universität","teile":[{"type":"mc","title":"Teil 1: Fünf kurze Texte","instruction":"Sie hören fünf kurze Texte. Sie hören jeden Text zweimal. Wählen Sie a, b oder c.","items":[{"transcript":"Liebe Studierende, eine wichtige Information: Die Vorlesung Einführung in die Psychologie am Donnerstag um 14 Uhr ist verschoben. Professor Schmidt ist auf einer Konferenz. Neuer Termin: Freitag um 14 Uhr, gleicher Raum. Mittwoch um 10 Uhr geht nicht, der Raum ist dann belegt. Bitte tragt euch in die Liste ein.","gender":"f","q":"Wann ist die Vorlesung jetzt?","opts":["Freitag um 14 Uhr.","Donnerstag um 14 Uhr.","Mittwoch um 10 Uhr."],"correct":0},{"transcript":"Achtung an alle Studenten: Die Bibliothek hat ab Montag neue Öffnungszeiten. Statt bis 20 Uhr sind wir nun bis 23 Uhr offen. Sonntags sind wir nicht geschlossen und auch nicht den ganzen Tag da, sondern von 12 bis 18 Uhr. Mehr Zeit zum Lernen, bitte respektiert die Ruhe für alle.","gender":"m","q":"Wann ist die Bibliothek jetzt sonntags offen?","opts":["Sonntags geschlossen.","Von 12 bis 18 Uhr.","Den ganzen Tag."],"correct":1},{"transcript":"Hallo Tom, hier ist Anna von der Uni. Du, wegen unserer Gruppenarbeit: Wir treffen uns nicht morgen und auch nicht nächste Woche, sondern erst am Donnerstag. Lisa ist krank, Tim hat einen Arzttermin. Donnerstag in der Bibliothek, dritter Stock, um 15 Uhr. Bring bitte deine Recherche mit.","gender":"f","q":"Wann ist das Gruppentreffen?","opts":["Nächste Woche.","Morgen.","Donnerstag um 15 Uhr."],"correct":2},{"transcript":"Liebe Erstsemester, willkommen an unserer Universität! Die Einführungswoche startet nächsten Montag. Wir bieten Führungen durch alle Gebäude, Treffen mit den Professoren und natürlich auch Partys am Abend. Ihr müsst euch nicht anmelden und auch kein Eintrittsgeld zahlen, einfach kommen. Das volle Programm steht online auf unserer Seite.","gender":"f","q":"Was muss man tun?","opts":["Sich anmelden.","Eintrittsgeld zahlen.","Einfach kommen."],"correct":2},{"transcript":"Hier ist die Mensa-Information. Heute haben wir folgende Gerichte: Pasta mit Tomatensoße für 4 Euro, Schnitzel mit Pommes 5 Euro 50, Salat-Buffet 4 Euro 50. Vegetarische Lasagne haben wir leider nicht heute, die war ausverkauft. Morgen ist die Lasagne wieder im Angebot. Pasta und Salat-Buffet gibt es den ganzen Tag.","gender":"m","q":"Was gibt es heute nicht?","opts":["Vegetarische Lasagne.","Salat-Buffet.","Pasta."],"correct":0}]},{"type":"match","title":"Teil 2: Ein Gespräch","instruction":"Sie hören ein Gespräch. Sie hören den Text einmal. Wer studiert was? Wählen Sie für jede Person einen Buchstaben (a–i).","lines":[{"speaker":"Lukas","gender":"m","text":"Hallo Lisa! Die neuen Vorlesungen fangen schon sehr bald an."},{"speaker":"Lisa","gender":"f","text":"Hallo Lukas! Fast alle aus unserer Gruppe haben sich schon entschieden."},{"speaker":"Lukas","gender":"m","text":"Mein Fach wird Medizin. Ab Oktober stehe ich in der Klinik."},{"speaker":"Lisa","gender":"f","text":"Du wolltest das schon als kleines Kind. Es passt wirklich zu dir."},{"speaker":"Lukas","gender":"m","text":"Studiert noch jemand von uns Psychologie?"},{"speaker":"Lisa","gender":"f","text":"Nein. Psychologie studiert keiner von uns."},{"speaker":"Lukas","gender":"m","text":"Du sitzt abends oft über dicken alten Gesetzbüchern."},{"speaker":"Lisa","gender":"f","text":"Ich bleibe bei Jura. Die erste Prüfung kommt im Winter."},{"speaker":"Lukas","gender":"m","text":"Tom redet nur noch über Rechner und Bildschirme."},{"speaker":"Lisa","gender":"f","text":"Tom hat sich für Informatik entschieden. Er übt schon an einem eigenen Projekt."},{"speaker":"Lukas","gender":"m","text":"Sara zeichnet ständig Häuser und Brücken."},{"speaker":"Lisa","gender":"f","text":"Sara geht in die Architektur. Ihr kleines Modell steht im Wohnheim auf dem Tisch."},{"speaker":"Lukas","gender":"m","text":"Studiert jemand von uns Biologie?"},{"speaker":"Lisa","gender":"f","text":"Nein. Biologie ist es auch nicht."},{"speaker":"Lukas","gender":"m","text":"Tim rechnet gern mit Geld und Märkten."},{"speaker":"Lisa","gender":"f","text":"Tim nimmt Wirtschaft. Die Vorlesung ist montags ganz früh."},{"speaker":"Lukas","gender":"m","text":"Dann sehen wir uns montags in der Kantine."},{"speaker":"Lisa","gender":"f","text":"Bis dahin lese ich die ersten Seiten heute noch einmal."}],"options":[{"letter":"a","text":"Psychologie"},{"letter":"b","text":"Architektur"},{"letter":"c","text":"Informatik"},{"letter":"d","text":"Biologie"},{"letter":"e","text":"Pädagogik"},{"letter":"f","text":"Jura"},{"letter":"g","text":"Sprachen"},{"letter":"h","text":"Wirtschaft"},{"letter":"i","text":"Medizin"}],"items":[{"person":"Lukas","correct":"i"},{"person":"Lisa","correct":"f"},{"person":"Tom","correct":"c"},{"person":"Sara","correct":"b"},{"person":"Tim","correct":"h"}]},{"type":"mc","title":"Teil 3: Fünf kurze Gespräche","instruction":"Sie hören fünf kurze Gespräche. Sie hören jedes Gespräch einmal. Wählen Sie a, b oder c.","items":[{"lines":[{"speaker":"Sekretärin","gender":"f","text":"Guten Tag, welches Fach möchten Sie studieren? Medizin, Biologie oder Chemie?"},{"speaker":"Student","gender":"m","text":"Eigentlich Medizin, aber der Notendurchschnitt ist zu hoch für mich."},{"speaker":"Sekretärin","gender":"f","text":"Wie wäre Biologie? Ähnliches Feld, aber leichter zu kommen. Chemie ist auch möglich, aber mehr Labor."},{"speaker":"Student","gender":"m","text":"Chemie mag ich nicht so. Biologie klingt gut, das mache ich."},{"speaker":"Sekretärin","gender":"f","text":"Gut, dann Biologie, die Anmeldung geht noch bis Freitag."}],"q":"Was studiert der Student?","opts":["Biologie.","Medizin.","Chemie."],"correct":0},{"lines":[{"speaker":"Studentin","gender":"f","text":"Wo finde ich Professor Bauers Büro? Hat er täglich Sprechstunde?"},{"speaker":"Mitarbeiterin","gender":"f","text":"Im Hauptgebäude, dritter Stock, Raum 305. Nicht täglich, nur einmal in der Woche."},{"speaker":"Studentin","gender":"f","text":"Ist er heute da? Heute ist Donnerstag."},{"speaker":"Mitarbeiterin","gender":"f","text":"Mittwochs hat er Sprechstunde, donnerstags ist er nicht da, und täglich auch nicht."},{"speaker":"Studentin","gender":"f","text":"Schade, dann komme ich nächsten Mittwoch. Danke für die Info."}],"q":"Wann ist die Sprechstunde?","opts":["Täglich.","Donnerstags.","Mittwochs."],"correct":2},{"lines":[{"speaker":"Studentin","gender":"f","text":"Welche Sprache muss ich lernen für mein Studium? Französisch, Spanisch oder Chinesisch?"},{"speaker":"Berater","gender":"m","text":"Für Internationale Beziehungen brauchen Sie zwei Sprachen. Englisch zählt schon als eine."},{"speaker":"Studentin","gender":"f","text":"Englisch habe ich schon, was noch? Französisch oder Spanisch sind beliebt, oder?"},{"speaker":"Berater","gender":"m","text":"Französisch oder Spanisch sind beliebt. Auch Chinesisch ist eine gute Wahl heute, aber schwerer."},{"speaker":"Studentin","gender":"f","text":"Spanisch, ich hatte schon einen Anfänger-Kurs, Französisch und Chinesisch wären neu."}],"q":"Welche Sprache nimmt sie?","opts":["Französisch.","Chinesisch.","Spanisch."],"correct":2},{"lines":[{"speaker":"Vater","gender":"m","text":"Wo wirst du studieren? Berlin, Hamburg, oder beide Städte nacheinander?"},{"speaker":"Tochter","gender":"f","text":"Berlin oder Hamburg, ich überlege noch. Beide auf einmal geht nicht."},{"speaker":"Vater","gender":"m","text":"Hamburg ist näher, berlin ist teurer, das musst du wissen."},{"speaker":"Tochter","gender":"f","text":"Aber Berlin ist spannender, ich entscheide mich für Berlin, nicht für Hamburg, und nicht für beide."},{"speaker":"Vater","gender":"m","text":"Okay, Berlin, dann suchen wir nächste Woche eine Wohnung."}],"q":"Wohin geht die Tochter?","opts":["Berlin.","Hamburg.","Beide."],"correct":0},{"lines":[{"speaker":"Sohn","gender":"m","text":"Mama, ich brauche Geld für meine Studienbücher. 150 Euro wären neu."},{"speaker":"Mutter","gender":"f","text":"Wie viel genau? 150 Euro, oder weniger? Ganz ohne Geld geht es nicht."},{"speaker":"Sohn","gender":"m","text":"150 Euro neu, aber ich kann die Hälfte sparen, wenn ich gebrauchte Bücher kaufe."},{"speaker":"Mutter","gender":"f","text":"Dann gebrauchte Bücher. 75 Euro ist okay, 150 ist zu viel, und nichts wäre unfair."},{"speaker":"Sohn","gender":"m","text":"Danke, Mama, ich bestelle die gebrauchten Bücher heute noch."}],"q":"Wie viel zahlt die Mutter?","opts":["150 Euro.","75 Euro.","Nichts."],"correct":1}]},{"type":"jn","title":"Teil 4: Interview","instruction":"Sie hören ein Interview mit Frau Hofer, einer Universitätsprofessorin. Sie hören das Interview zweimal. Ja oder Nein?","transcript":[{"speaker":"Reporter","gender":"m","text":"Frau Professor Hofer, Sie unterrichten Geschichte an der Universität München seit 15 Jahren. Wie sind Sie Professorin geworden?"},{"speaker":"Hofer","gender":"f","text":"Ich war immer fasziniert von der deutschen Geschichte. Nach dem Studium habe ich promoviert, dann ein paar Jahre an einem Institut gearbeitet. Mit 35 habe ich die Professur bekommen — relativ jung für die Universität."},{"speaker":"Reporter","gender":"m","text":"Wie sind Ihre Studenten heute?"},{"speaker":"Hofer","gender":"f","text":"Anders als vor 15 Jahren. Sie nutzen viel mehr digitale Hilfsmittel, lesen aber weniger Bücher. Manche kommen schon mit Vorwissen aus dem Internet — das ist gut. Andere wissen weniger über Basis-Geschichte, das ist schade."},{"speaker":"Reporter","gender":"m","text":"Welche Themen sind am beliebtesten?"},{"speaker":"Hofer","gender":"f","text":"Das 20. Jahrhundert — vor allem Weltkriege und Nachkriegszeit. Mittelalter ist weniger beliebt, leider. Die Studenten finden es zu fern und abstrakt. Aber für das Verständnis der Gegenwart ist das Mittelalter wichtig."},{"speaker":"Reporter","gender":"m","text":"Forschen Sie auch?"},{"speaker":"Hofer","gender":"f","text":"Ja, mein aktuelles Projekt ist über Frauen im 19. Jahrhundert in Bayern. Sehr spezifisch, aber spannend. Im nächsten Jahr erscheint mein Buch dazu."},{"speaker":"Reporter","gender":"m","text":"Was machen Sie privat?"},{"speaker":"Hofer","gender":"f","text":"Auch lesen — aber nur Romane, keine Geschichtsbücher. Beruflich genug davon. Auch Wandern in den Bergen. Ich lebe in München, da bin ich schnell in den Alpen."}],"items":[{"q":"Frau Professor Hofer hat sehr jung ihre Professur bekommen.","correct":"ja"},{"q":"Studenten lesen heute mehr Bücher als früher.","correct":"nein"},{"q":"Das Mittelalter ist sehr beliebt bei Studenten.","correct":"nein"},{"q":"Sie schreibt gerade ein Buch über Frauen im 19. Jahrhundert.","correct":"ja"},{"q":"Privat liest sie viele Geschichtsbücher.","correct":"nein"}]}]};
